package vn.svframe.worldboss;
import org.junit.jupiter.api.Test;
import java.nio.file.*;import java.util.*;import vn.svframe.fantasyhub.core.hero.HeroCatalog;
import static org.junit.jupiter.api.Assertions.*;
class BossConfigTest {
 private Path config()throws Exception{return Files.createTempDirectory("worldboss-config");}
 private void bosses(Path p,String entries)throws Exception{Files.writeString(p.resolve("bosses.json"),"{\"bosses\":["+entries+"]}");}
 private String boss(){return "{\"id\":\"new_web\",\"name\":\"Web Guardian\",\"type\":\"class\",\"classId\":\"SPIDER_MAN\",\"skillIds\":[\"WEB_SHOOTER_BARRAGE\"],\"cooldownMultiplier\":1.4,\"damageMultiplier\":0.8,\"winReward\":24,\"lossReward\":6,\"phases\":[{\"healthBelow\":0.7,\"cooldownMultiplier\":0.5,\"damageMultiplier\":2,\"skillIds\":[\"WEB_BLITZ\"]}]}";}
 private void validate(String id,List<String> skills){try{var hero=HeroCatalog.defaults().hero(id);for(var skill:skills)if(hero.abilities().stream().noneMatch(a->a.key().equals(skill)||a.id().equals(skill)))throw new IllegalArgumentException("Unknown skill "+skill);}catch(java.io.IOException ex){throw new IllegalStateException(ex);}}
 @Test void newBossControlsRotationPhasesAndRewardsFromConfiguration()throws Exception{
  var p=config();bosses(p,boss());var cfg=new BossConfig(p);cfg.validateActors(this::validate);var b=cfg.boss("new_web");assertEquals(List.of("WEB_SHOOTER_BARRAGE"),b.rotation(1));assertEquals(List.of("WEB_BLITZ"),b.rotation(.69));assertEquals(1,b.phase(1));assertEquals(2,b.phase(.69));assertEquals(.7,b.cooldown(.69),.0001);assertEquals(1.6,b.damage(.69),.0001);assertEquals(24,b.win(cfg.rewards));assertEquals(6,b.loss(cfg.rewards));
 }
 @Test void duplicateBossIdsAreRejectedWithPath()throws Exception{var p=config();bosses(p,boss()+","+boss());var error=assertThrows(IllegalArgumentException.class,()->new BossConfig(p));assertTrue(error.getMessage().contains("bosses[1].id"));}
 @Test void missingTypeSpecificFieldsAreRejected()throws Exception{var p=config();bosses(p,"{\"id\":\"bad\",\"name\":\"Bad\",\"type\":\"class\"}");assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("classId"));bosses(p,"{\"id\":\"bad\",\"name\":\"Bad\",\"type\":\"pokemon\"}");assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("properties"));}
 @Test void badClassAndCrossClassSkillAreRejectedBeforeInstall()throws Exception{var p=config();bosses(p,boss().replace("SPIDER_MAN","MADE_UP"));var cfg=new BossConfig(p);assertTrue(assertThrows(IllegalArgumentException.class,()->cfg.validateActors(this::validate)).getMessage().contains("new_web"));bosses(p,boss().replace("WEB_SHOOTER_BARRAGE","MJOLNIR_THROW"));var cfg2=new BossConfig(p);assertThrows(IllegalArgumentException.class,()->cfg2.validateActors(this::validate));}
 @Test void invalidReloadRetainsWorkingConfiguration()throws Exception{var p=config();bosses(p,boss());var manager=new BossConfig.Manager(p,this::validate);var before=manager.current();bosses(p,boss().replace("SPIDER_MAN","MADE_UP"));assertThrows(IllegalArgumentException.class,manager::reload);assertSame(before,manager.current());Files.writeString(p.resolve("bosses.json"),"{broken");assertThrows(java.io.IOException.class,manager::reload);assertSame(before,manager.current());}
 @Test void explicitScheduleMapsOnlyChosenBossesAndArenas()throws Exception{var p=config();bosses(p,boss());new BossConfig(p);Files.writeString(p.resolve("locations.json"),"{\"locations\":[{\"id\":\"north\",\"dimension\":\"minecraft:overworld\",\"x\":0,\"y\":80,\"z\":0},{\"id\":\"south\",\"dimension\":\"minecraft:overworld\",\"x\":100,\"y\":80,\"z\":0}]}");Files.writeString(p.resolve("schedule.json"),"{\"entries\":[{\"time\":\"18:00\",\"bossIds\":[\"new_web\"],\"arenaIds\":[\"north\"]}]}");var cfg=new BossConfig(p);assertEquals(List.of("18:00"),cfg.scheduleTimes());var assignments=cfg.assignments("18:00",20);assertEquals(1,assignments.size());assertEquals("north",assignments.getFirst().arena());assertEquals("new_web",assignments.getFirst().boss());}
 @Test void generatedFirstStartDefaultsMatchEveryShippedSampleAndValidateSkills()throws Exception{
  var generated=new BossConfig(config());var sample=config();for(String file:List.of("bosses.json","locations.json","schedule.json","rewards.json"))Files.copy(Path.of("config",file),sample.resolve(file));var expected=new BossConfig(sample);generated.validateActors(this::validate);expected.validateActors(this::validate);var json=new com.google.gson.Gson();assertEquals(json.toJsonTree(expected.bosses),json.toJsonTree(generated.bosses));assertEquals(json.toJsonTree(expected.locations),json.toJsonTree(generated.locations));assertEquals(json.toJsonTree(expected.schedule),json.toJsonTree(generated.schedule));assertEquals(json.toJsonTree(expected.rewards),json.toJsonTree(generated.rewards));assertEquals(18,generated.boss("web_guardian").win(generated.rewards));
 }
 @Test void nullNestedConfigurationValuesReportTheirPaths()throws Exception{
  var p=config();bosses(p,boss().replace("\"skillIds\":[\"WEB_SHOOTER_BARRAGE\"]","\"skillIds\":null"));assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("skillIds"));
  bosses(p,"null");assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("bosses[0]"));bosses(p,boss());new BossConfig(p);Files.writeString(p.resolve("schedule.json"),"{\"entries\":[null]}");assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("schedule.entries[0]"));
 }
 @Test void secondPrecisionEntriesValidateAndSelectTheirBoss()throws Exception{var p=config();bosses(p,boss());new BossConfig(p);Files.writeString(p.resolve("locations.json"),"{\"locations\":[{\"id\":\"qa\",\"dimension\":\"minecraft:overworld\",\"x\":0,\"y\":80,\"z\":0}]}");Files.writeString(p.resolve("schedule.json"),"{\"entries\":[{\"time\":\"18:00:30\",\"bossIds\":[\"new_web\"],\"arenaIds\":[\"qa\"]}]}");var cfg=new BossConfig(p);assertEquals(1,cfg.assignments("18:00:30",0).size());assertTrue(cfg.assignments("18:00",0).isEmpty());}
 @Test void invalidPhasesAndUnknownScheduleReferencesExplainLocation()throws Exception{var p=config();bosses(p,boss().replace("0.7","1.2"));assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("phases[0].healthBelow"));bosses(p,boss());new BossConfig(p);Files.writeString(p.resolve("schedule.json"),"{\"entries\":[{\"time\":\"18:00\",\"bossIds\":[\"ghost\"]}]}");assertTrue(assertThrows(IllegalArgumentException.class,()->new BossConfig(p)).getMessage().contains("bossIds"));}
 @Test void telegraphTimingAndColorAreConfigurableAndValidated()throws Exception{
  var p=config();bosses(p,boss().replace("\"id\":\"new_web\"","\"id\":\"new_web\",\"windupSeconds\":4,\"telegraphColor\":\"44AAFF\""));
  var json=new com.google.gson.Gson().toJsonTree(new BossConfig(p).boss("new_web")).getAsJsonObject();assertEquals(4,json.get("windupSeconds").getAsInt());assertEquals("44AAFF",json.get("telegraphColor").getAsString());
  bosses(p,boss().replace("\"id\":\"new_web\"","\"id\":\"new_web\",\"windupSeconds\":0"));assertThrows(IllegalArgumentException.class,()->new BossConfig(p));
 }
 @Test void explicitScheduleCannotReservePersonalArena()throws Exception{
  var p=config();bosses(p,boss());new BossConfig(p);
  Files.writeString(p.resolve("locations.json"),"{\"locations\":[{\"id\":\"private\",\"personal\":true,\"dimension\":\"minecraft:overworld\",\"x\":0,\"y\":80,\"z\":0}]}");
  Files.writeString(p.resolve("schedule.json"),"{\"entries\":[{\"time\":\"18:00\",\"bossIds\":[\"new_web\"],\"arenaIds\":[\"private\"]}]}");
  assertTrue(new BossConfig(p).assignments("18:00",0).isEmpty());
 }
}
